arguments.command:
cd /workspace/project && python3 - <<'EOF'
p='src/roce_packet.c'
s=open(p).read()
s=s.replace("""static uint32_t load32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) |
           p[3];
}""","""static uint32_t load32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) |
           p[3];
}
/* ICRC is the only little-endian multibyte field on the wire. */
static uint32_t load32le(const uint8_t *p) {
    return ((uint32_t)p[3] << 24) | ((uint32_t)p[2] << 16) | ((uint32_t)p[1] << 8) |
           p[0];
}""")
s=s.replace("if (load32(frame + frame_len - EPIC_ICRC_LEN) != epic_compute_icrc(frame, frame_len))",
            "if (load32le(frame + frame_len - EPIC_ICRC_LEN) != epic_compute_icrc(frame, frame_len))")
open(p,'w').write(s)
EOF
cd /workspace && make -s -C project BUILD=/tmp/mkbuild -j2 && python3 - <<'EOF'
import json,subprocess,sys
ex=json.load(open('examples.json'))
for e in ex:
    p=subprocess.run([sys.executable,'-I','-B','project/solver.py'],input=json.dumps(e['input']).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    got=json.loads(p.stdout.decode())
    print(e['name'], 'MATCH' if got==e['output'] else 'DIFF')
    if got!=e['output']:
        for g,w in zip(got['cases'],e['output']['cases']):
            for k in g:
                if g[k]!=w[k]: print('  ',k,'\n    got ',g[k],'\n    want',w[k])
EOF
